/**
 * One source of truth for a replay item's identity across every SDK shape
 * (camel/snake) and generation (modern lineage vs legacy direct keying). The
 * progress parser and the final-result externalizer used to hand-roll this remap
 * independently, so a field rename drifted between them (the sourceSpanId ->
 * originalSpanId regression). Everything resolves identity through here now.
 */
/** Original-trace id; last two are deprecated pre-rename aliases. */
export const REPLAY_ORIGINAL_TRACE_ID_KEYS = [
    "originalTraceId",
    "original_trace_id",
    "sourceTraceId",
    "source_trace_id",
];
export const REPLAY_TRACE_ID_KEYS = ["traceId", "trace_id"];
const REPLAY_LOCAL_TRACE_ID_KEYS = ["replayTraceId", "replay_trace_id"];
export function readTraceIdAlias(rec, keys) {
    for (const key of keys) {
        const value = rec[key];
        if (typeof value === "string" && value.length > 0) {
            return value;
        }
    }
    return null;
}
export function resolveReplayItemIdentity(rawItem) {
    if (!rawItem || typeof rawItem !== "object") {
        return {
            originalTraceId: null,
            traceId: null,
            replayTraceId: null,
            persistKey: null,
        };
    }
    const rec = rawItem;
    const originalTraceId = readTraceIdAlias(rec, REPLAY_ORIGINAL_TRACE_ID_KEYS);
    const traceId = readTraceIdAlias(rec, REPLAY_TRACE_ID_KEYS);
    const replayTraceId = readTraceIdAlias(rec, REPLAY_LOCAL_TRACE_ID_KEYS);
    // Lineage wins; the direct server traceId is only the key on oldest SDKs.
    const persistKey = originalTraceId ?? traceId;
    return { originalTraceId, traceId, replayTraceId, persistKey };
}
